changeSet.sql:
DROP TABLE IF EXISTS nexus.t225_ref_manifest CASCADE;
DROP TABLE IF EXISTS nexus.t225_ref_assign CASCADE;
DROP TABLE IF EXISTS nexus.t225_ref_orphan CASCADE;
DROP TABLE IF EXISTS nexus.t225_tokens CASCADE;
DROP TABLE IF EXISTS nexus.t225_other_part CASCADE;
DROP FUNCTION IF EXISTS nexus.t225_sleepy();
DROP TABLE IF EXISTS nexus.chunks_new CASCADE;
DROP TABLE IF EXISTS nexus.taxonomy_centroids_new CASCADE;
DELETE FROM nexus.service_tokens WHERE label = 'p225';

CREATE TABLE nexus.chunks_new (
    LIKE nexus.chunks INCLUDING DEFAULTS INCLUDING GENERATED INCLUDING CONSTRAINTS,
    embedding_model text NOT NULL
) PARTITION BY LIST (embedding_model);
ALTER TABLE nexus.chunks_new
    ADD CONSTRAINT chunks_new_pk PRIMARY KEY (tenant_id, collection, chash, embedding_model);

CREATE TABLE nexus.taxonomy_centroids_new (
    LIKE nexus.taxonomy_centroids INCLUDING DEFAULTS INCLUDING GENERATED INCLUDING CONSTRAINTS,
    embedding_model text NOT NULL
) PARTITION BY LIST (embedding_model);
ALTER TABLE nexus.taxonomy_centroids_new
    ADD CONSTRAINT taxonomy_centroids_new_pk PRIMARY KEY (tenant_id, collection, topic_id, embedding_model);

-- Replay every non-unique index of the live tables on the scratch parents (index names get a _new suffix).
DO $replay$
DECLARE
    r record;
BEGIN
    FOR r IN
        SELECT i.tablename, i.indexname, i.indexdef
          FROM pg_catalog.pg_indexes i
         WHERE i.schemaname = 'nexus'
           AND i.tablename IN ('chunks', 'taxonomy_centroids')
           AND i.indexdef NOT LIKE 'CREATE UNIQUE%'
    LOOP
        EXECUTE replace(replace(r.indexdef,
                                ' ON nexus.' || r.tablename || ' ', ' ON nexus.' || r.tablename || '_new '),
                        'INDEX ' || r.indexname || ' ', 'INDEX ' || r.indexname || '_new ');
    END LOOP;
END
$replay$;

ALTER TABLE nexus.chunks_new ADD CONSTRAINT chunks_new_collection_fk
    FOREIGN KEY (tenant_id, collection, embedding_model)
    REFERENCES nexus.catalog_collections (tenant_id, name, embedding_model) ON DELETE RESTRICT;

ALTER TABLE nexus.chunks_new ENABLE ROW LEVEL SECURITY;
ALTER TABLE nexus.chunks_new FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON nexus.chunks_new
    USING      (tenant_id = current_setting('nexus.tenant', true))
    WITH CHECK (tenant_id = current_setting('nexus.tenant', true));
CREATE POLICY chunks_gate_probe_owner_read ON nexus.chunks_new
    FOR SELECT TO CURRENT_USER USING (true);
GRANT SELECT, INSERT, UPDATE, DELETE, MAINTAIN ON nexus.chunks_new TO nexus_svc;

ALTER TABLE nexus.taxonomy_centroids_new ENABLE ROW LEVEL SECURITY;
ALTER TABLE nexus.taxonomy_centroids_new FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON nexus.taxonomy_centroids_new
    USING      (tenant_id = current_setting('nexus.tenant', true))
    WITH CHECK (tenant_id = current_setting('nexus.tenant', true));
GRANT SELECT, INSERT, UPDATE, DELETE ON nexus.taxonomy_centroids_new TO nexus_svc;

-- Referencing tables: the manifest (deferrable, no delete action), the topic assignments and the
-- orphaned-at table (delete cascade). Each has a 4-column foreign key onto the partitioned parent.
CREATE TABLE nexus.t225_ref_manifest (
    tenant_id       text   NOT NULL,
    doc_id          text   NOT NULL,
    position        int    NOT NULL,
    collection      text   NOT NULL,
    chash           bytea  NOT NULL,
    embedding_model text   NOT NULL,
    CONSTRAINT t225_ref_manifest_pk PRIMARY KEY (tenant_id, doc_id, position),
    CONSTRAINT t225_ref_manifest_chunk_fk FOREIGN KEY (tenant_id, collection, chash, embedding_model)
        REFERENCES nexus.chunks_new (tenant_id, collection, chash, embedding_model)
        ON UPDATE CASCADE DEFERRABLE INITIALLY IMMEDIATE
);
CREATE TABLE nexus.t225_ref_assign (
    tenant_id       text   NOT NULL,
    doc_id          text   NOT NULL,
    topic_id        bigint NOT NULL,
    collection      text   NOT NULL,
    chash           bytea  NOT NULL,
    embedding_model text   NOT NULL,
    CONSTRAINT t225_ref_assign_pk PRIMARY KEY (tenant_id, doc_id, topic_id),
    CONSTRAINT t225_ref_assign_chunk_fk FOREIGN KEY (tenant_id, collection, chash, embedding_model)
        REFERENCES nexus.chunks_new (tenant_id, collection, chash, embedding_model)
        ON UPDATE CASCADE ON DELETE CASCADE
);
CREATE TABLE nexus.t225_ref_orphan (
    tenant_id       text   NOT NULL,
    collection      text   NOT NULL,
    chash           bytea  NOT NULL,
    embedding_model text   NOT NULL,
    CONSTRAINT t225_ref_orphan_pk PRIMARY KEY (tenant_id, collection, chash, embedding_model),
    CONSTRAINT t225_ref_orphan_chunk_fk FOREIGN KEY (tenant_id, collection, chash, embedding_model)
        REFERENCES nexus.chunks_new (tenant_id, collection, chash, embedding_model)
        ON UPDATE CASCADE ON DELETE CASCADE
);
ALTER TABLE nexus.t225_ref_manifest ENABLE ROW LEVEL SECURITY;
ALTER TABLE nexus.t225_ref_manifest FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON nexus.t225_ref_manifest
    USING      (tenant_id = current_setting('nexus.tenant', true))
    WITH CHECK (tenant_id = current_setting('nexus.tenant', true));
GRANT SELECT, INSERT, UPDATE, DELETE ON nexus.t225_ref_manifest TO nexus_svc;
GRANT SELECT, INSERT, UPDATE, DELETE ON nexus.t225_ref_assign TO nexus_svc;
GRANT SELECT, INSERT, UPDATE, DELETE ON nexus.t225_ref_orphan TO nexus_svc;

-- A stand-in for nexus.service_tokens: the tenant-creation trigger function is attached to this one in tests.
CREATE TABLE nexus.t225_tokens (tenant_id text NOT NULL);
GRANT SELECT, INSERT ON nexus.t225_tokens TO nexus_svc;
